// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    Caller caller;

    function setUp() public {
        caller = new Caller();
        vm.prank(address(caller));
        c = new SimpleWallet();
    }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 2 ** 100);
        vm.deal(address(c), amount);
        caller.callWithdraw(c, amount);
        assertTrue(address(c).balance == 0);
    }
}

contract Caller {
    receive() external payable {}
    function callWithdraw(SimpleWallet c, uint256 v) external {
        c.withdraw(v);
    }
}
